from al_lib import *


def R(code, name, short, pop, pcrel, dev, unrest, auto, reg, tr, sec, infra, edu, health, env, mix, desc, E):
    return dict(code=code, name=name, short=short, pop=pop, pcrel=pcrel, dev=dev, unrest=unrest, auto=auto, reg=reg, tr=tr,
                sec={"ind": sec[0], "agr": sec[1], "srv": sec[2], "res": sec[3]}, infra=infra, edu=edu, health=health, env=env, mix=mix, desc=desc, E=E)


def E25(ps, ashm, psd, nisma, pm, lb, oth, mnsh=0.02, pl=0.08, paa=0.02):
    """результат 2025 года по округу (в %): список ASHM делится между ПД (+республиканцы), Партией Свободы, аграриями и партиями меньшинств
    по их местам во фракции и региональной опоре; NISMA–SHB («Албания становится», «Тюрье», LDPSH) — в слот 9."""
    pd = ashm * (1.0 - mnsh - pl - paa)
    return [ps, round(pd, 2), psd, lb, round(ashm * paa, 2), pm, oth, round(ashm * pl, 2), round(ashm * mnsh, 2), nisma]


